/* Iki seviyeli akordeon menu + kaldigin yerden devam (ES3, OS 5 uyumlu)
   MENU = [ {t:'Ust baslik', g:[ {t:'Alt baslik', i:[ 'Etiket', [baslik, href], ... ]} ]} ] */
var MENU_ROOT = '';

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function fileOf(h) { var a = String(h).split('/'); return a[a.length - 1]; }
function curFile() {
  var p = '';
  try { p = location.pathname || ''; } catch (e) {}
  return fileOf(p) || 'index.html';
}
/* [ust, alt, sira] ya da null; match: fn(link) */
function findLink(test) {
  var a, b, i, it;
  for (a = 0; a < MENU.length; a++) {
    for (b = 0; b < MENU[a].g.length; b++) {
      for (i = 0; i < MENU[a].g[b].i.length; i++) {
        it = MENU[a].g[b].i[i];
        if (typeof it !== 'string' && test(it)) { return { a: a, b: b, item: it }; }
      }
    }
  }
  return null;
}
function findByFile(file) { return findLink(function (it) { return fileOf(it[1]) === file; }); }
function findByHref(href) { return findLink(function (it) { return it[1] === href; }); }

function getY() {
  return window.pageYOffset ||
    (document.documentElement && document.documentElement.scrollTop) ||
    (document.body && document.body.scrollTop) || 0;
}

function resumeHtml(cur) {
  var last = sget('last'), f, y;
  if (!last) { return ''; }
  f = findByHref(last);
  if (!f || fileOf(f.item[1]) === cur) { return ''; }
  y = parseInt(sget('y'), 10) || 0;
  return '<div class="resume"><b>Kald&#305;&#287;&#305;n yer:</b><br>' +
    '<a href="' + MENU_ROOT + f.item[1] + '" onclick="sset(\'resume\',\'1\');return true;">' +
    '&#9654; ' + esc(f.item[0]) + '</a>' + (y > 100 ? '<br><small>(sayfan&#305;n i&ccedil;inden devam eder)</small>' : '') + '</div>';
}

function buildMenu(cur, oa, ob) {
  var h = '', a, b, i, it, grp, cls;
  h += '<div class="mhead"><a href="' + MENU_ROOT + 'index.html">Ana sayfa</a></div>';
  h += resumeHtml(cur);
  for (a = 0; a < MENU.length; a++) {
    h += '<div class="mtop' + (a === oa ? ' open' : '') + '" id="mt' + a + '">';
    h += '<a href="#" class="mtt" onclick="return mtop(' + a + ');">' +
         '<span class="t-plus">[+]</span><span class="t-minus">[&minus;]</span> ' + esc(MENU[a].t) + '</a>';
    h += '<div class="mtbody">';
    for (b = 0; b < MENU[a].g.length; b++) {
      grp = MENU[a].g[b];
      cls = 'mg' + ((a === oa && b === ob) ? ' open' : '');
      h += '<div class="' + cls + '" id="mg' + a + '_' + b + '">';
      h += '<a href="#" class="mgt" onclick="return mgrp(' + a + ',' + b + ');">' +
           '<span class="m-plus">[+]</span><span class="m-minus">[&minus;]</span> ' + esc(grp.t) + '</a>';
      h += '<ul class="mlist">';
      for (i = 0; i < grp.i.length; i++) {
        it = grp.i[i];
        if (typeof it === 'string') {
          h += '<li class="mlabel">' + esc(it) + '</li>';
        } else {
          h += '<li' + (fileOf(it[1]) === cur ? ' class="cur"' : '') + '><a href="' + MENU_ROOT + it[1] + '">' + esc(it[0]) + '</a></li>';
        }
      }
      h += '</ul></div>';
    }
    h += '</div></div>';
  }
  return h;
}

function saveOpen() {
  var a, b, oa = -1, ob = -1, el;
  for (a = 0; a < MENU.length; a++) {
    el = document.getElementById('mt' + a);
    if (el && hasClass(el, 'open')) { oa = a; }
  }
  if (oa > -1) {
    for (b = 0; b < MENU[oa].g.length; b++) {
      el = document.getElementById('mg' + oa + '_' + b);
      if (el && hasClass(el, 'open')) { ob = b; }
    }
  }
  sset('open', oa + ',' + ob);
}

/* ust baslik: ayni anda tek ust baslik acik */
function mtop(a) {
  var i, el = document.getElementById('mt' + a), was = el && hasClass(el, 'open');
  for (i = 0; i < MENU.length; i++) {
    el = document.getElementById('mt' + i);
    if (el) { removeClass(el, 'open'); }
  }
  if (!was) { addClass(document.getElementById('mt' + a), 'open'); }
  saveOpen();
  return false;
}
/* alt baslik: ust baslik icinde ayni anda tek alt baslik acik */
function mgrp(a, b) {
  var i, el = document.getElementById('mg' + a + '_' + b), was = el && hasClass(el, 'open');
  for (i = 0; i < MENU[a].g.length; i++) {
    el = document.getElementById('mg' + a + '_' + i);
    if (el) { removeClass(el, 'open'); }
  }
  if (!was) { addClass(document.getElementById('mg' + a + '_' + b), 'open'); }
  saveOpen();
  return false;
}

function initMenu(root) {
  var cur, side, box, f, oa = -1, ob = -1, saved, parts, restoreY = 0, doRestore = false, item;
  MENU_ROOT = root || '';
  cur = curFile();
  f = findByFile(cur);

  if (f) { oa = f.a; ob = f.b; sset('open', oa + ',' + ob); }
  else {
    saved = sget('open');
    if (saved) {
      parts = saved.split(',');
      oa = parseInt(parts[0], 10); ob = parseInt(parts[1], 10);
      if (isNaN(oa)) { oa = -1; }
      if (isNaN(ob)) { ob = -1; }
    } else { oa = 0; }
  }

  side = document.getElementById('side');
  if (side) { side.innerHTML = buildMenu(cur, oa, ob); }
  box = document.getElementById('resume-box');
  if (box) { box.innerHTML = resumeHtml(cur); }

  if (!f) { return; }   /* ana sayfa: kaldigin yeri degistirme */
  item = f.item;

  if (sget('resume') === '1' && sget('last') === item[1]) {
    restoreY = parseInt(sget('y'), 10) || 0;
    doRestore = restoreY > 0;
  }
  sset('resume', '0');
  if (sget('last') !== item[1]) { sset('last', item[1]); sset('y', 0); }

  function save() { sset('last', item[1]); sset('y', getY()); }
  function startSaving() {
    setInterval(save, 1500);
    window.onunload = save;
    window.onbeforeunload = save;
  }
  if (doRestore) {
    window.onload = function () {
      setTimeout(function () { try { window.scrollTo(0, restoreY); } catch (e) {} startSaving(); }, 150);
    };
  } else {
    startSaving();
  }
}
